      />
      <mat-datepicker-toggle matIconSuffix [for]="picker" />
      <mat-datepicker #picker />
    </mat-form-field>
  </div>

  @if (state() === 'loading') {
    <div class="state" data-testid="movies-loading">
      <mat-spinner diameter="32" />
      <span>Loading…</span>
