          <mat-card-content>
            <h2 class="movie-title" data-testid="movie-title">{{ entry.movie.title }}</h2>
            <div class="movie-meta">
              <span data-testid="movie-genre">{{ entry.movie.genre }}</span>
              <span data-testid="movie-runtime">{{ entry.movie.runtimeMinutes }} min</span>
              <span data-testid="movie-format">{{ entry.movie.format }}</span>
            </div>
            <div class="screenings">
              @for (screening of entry.screenings; track screening.id) {
                <button
                  mat-stroked-button
                  data-testid="screening-button"
